select pg_temp.reject('update public.external_commission_terms set basis_points=9000','approved terms immutable');
select pg_temp.make_order(2);
select pg_temp.make_order(3,null);
select pg_temp.make_order(4,0);
select pg_temp.make_order(5,8000,true);
set local role service_role;
select public.process_external_commissions();select public.process_external_commissions();
