select pg_temp.reject('select public.perform_admin_external_settlement_action(jsonb_build_object(''request_id'',gen_random_uuid(),''action'',null,''id'',current_setting(''qa.batch'')::jsonb->>''id'',''expected_revision'',1,''reason'',''Null action must not approve''))','null action rejected');
select pg_temp.reject('select public.perform_admin_external_settlement_action(jsonb_build_object(''request_id'',gen_random_uuid(),''action'',''review_batch'',''id'',current_setting(''qa.batch'')::jsonb->>''id'',''expected_revision'',1,''reason'',''Review missing destination''))','missing destination blocks review');
select pg_temp.reject('select public.perform_admin_external_settlement_action(current_setting(''qa.scope'')::jsonb||jsonb_build_object(''request_id'',gen_random_uuid(),''action'',''prepare_batch'',''reason'',''No duplicate eligible allocation''))','frozen awards cannot be allocated twice');
select set_config('request.jwt.claims','{"sub":"ac570000-0000-4000-8000-000000000013","role":"authenticated"}',true);
select pg_temp.check_true(public.get_partner_external_settlement_workspace('{}')->'commissions'='[]','other creator sees no commissions');
select pg_temp.reject('select public.get_partner_external_settlement_workspace(''{"affiliate_id":"ac570000-0000-4000-8000-000000000003"}'')','creator cannot forge affiliate scope');
select pg_temp.reject('select public.creator_connect_context(''acct_fixture'',false)','uncontracted creator cannot connect this scope');
select set_config('request.jwt.claims','{"sub":"ac570000-0000-4000-8000-000000000012","role":"authenticated"}',true);
