set local role authenticated;
select set_config('qa.batch',public.perform_admin_external_settlement_action(jsonb_build_object('request_id',gen_random_uuid(),'action','review_batch','id',current_setting('qa.batch')::jsonb->>'id','expected_revision',1,'reason','Review exact frozen test batch'))::text,true);
select pg_temp.reject('select public.perform_admin_external_settlement_action(jsonb_build_object(''request_id'',gen_random_uuid(),''action'',''approve_batch'',''id'',current_setting(''qa.batch'')::jsonb->>''id'',''expected_revision'',1,''reason'',''Stale revision rejected''))','stale approval rejected');
select set_config('qa.batch',public.perform_admin_external_settlement_action(jsonb_build_object('request_id',gen_random_uuid(),'action','approve_batch','id',current_setting('qa.batch')::jsonb->>'id','expected_revision',2,'reason','Approve reviewed test batch'))::text,true);
