select pg_temp.check_true((select count(*)=0 from public.claim_creator_transfer_jobs('acct_fixture',true)),'live worker cannot claim test transfer');
select set_config('qa.job',(select value::text from public.claim_creator_transfer_jobs('acct_fixture',false) value),true);
