select pg_temp.reject('select public.finish_creator_transfer_job(jsonb_build_object(''id'',current_setting(''qa.job9'')::jsonb->>''id'',''lease_token'',current_setting(''qa.job9'')::jsonb->>''lease_token'',''status'',''succeeded'',''provider_id'',''tr_order9''))','old worker cannot finish after reacquisition');
select set_config('qa.receipt9',(current_setting('qa.job9.new')::jsonb||jsonb_build_object('provider_id','tr_order9','amount_reversed',0,'observed_at',clock_timestamp()))::text,true);
