select set_config('qa.partial9',jsonb_build_object('order_id',(select order_id from test_external_orders where n=9),'provider_event_id','evt_partial9','reason','Verified partial refund needs review','hold_type','refund_partial','verified_amount_minor',1000)::text,true);
