select pg_temp.check_true(not exists(select 1 from public.external_commission_ledger l join public.external_commission_awards a on a.id=l.award_id where a.order_id=(select order_id from test_external_orders where n=9) and l.kind='reversed'),'partial refund does not silently claw back full commission');
