select public.hold_external_commission_order(jsonb_build_object('order_id',(select order_id from test_external_orders where n=9),'provider_event_id','evt_dispute9','reason','Opened dispute is a review hold','hold_type','dispute','verified_amount_minor',10000));
select pg_temp.check_true((select status='held' from public.external_commission_awards where order_id=(select order_id from test_external_orders where n=9)),'opened dispute is not automatic full clawback');
select public.hold_external_commission_order(jsonb_build_object('order_id',(select order_id from test_external_orders where n=9),'provider_event_id','evt_full9','reason','Verified complete refund after partial','hold_type','refund_full','verified_amount_minor',10000));
select public.hold_external_commission_order(current_setting('qa.partial9')::jsonb);
select public.hold_external_commission_order(jsonb_build_object('order_id',(select order_id from test_external_orders where n=9),'provider_event_id','evt_latedispute9','reason','Late dispute cannot undo full refund','hold_type','dispute','verified_amount_minor',10000));
select pg_temp.make_order(10);select public.process_external_commissions();
select pg_temp.check_true((select status='reversed' from public.external_commission_awards where order_id=(select order_id from test_external_orders where n=9)),'partial full partial cannot downgrade strongest reversal');
