select pg_temp.reject('select public.perform_admin_external_settlement_action(current_setting(''qa.scope'')::jsonb||jsonb_build_object(''request_id'',gen_random_uuid(),''action'',''prepare_batch'',''reason'',''Cannot pay while reversal unresolved''))','new earnings blocked while recovery unresolved');
