select set_config('qa.next.start',(clock_timestamp()+interval '1 minute')::text,true);
set local role authenticated;
select set_config('qa.next.terms',public.configure_admin_external_commission_terms(current_setting('qa.terms.input')::jsonb||jsonb_build_object('request_id',gen_random_uuid(),'expected_version',1,'effective_from',current_setting('qa.next.start'),'reason','Future operational binding of same canonical rate'))::text,true);
select public.perform_admin_external_settlement_action(jsonb_build_object('request_id',gen_random_uuid(),'action','approve_terms','id',current_setting('qa.next.terms')::jsonb->>'id','expected_revision',1,'reason','Approve future version without rewriting history'));
reset role;
select pg_temp.make_order(11,8000,false,current_setting('qa.old.purchase.at')::timestamptz);
select pg_temp.make_order(12,8000,false,current_setting('qa.next.start')::timestamptz+interval '1 second');
select public.process_external_commissions();
select pg_temp.check_true((select commission_minor=2000 and terms_id=(current_setting('qa.terms')::jsonb->>'id')::uuid from public.external_commission_awards where order_id=(select order_id from test_external_orders where n=11)),'delayed purchase uses historical terms');
select pg_temp.check_true((select commission_minor=2000 and terms_id=(current_setting('qa.next.terms')::jsonb->>'id')::uuid and status='held' from public.external_commission_awards where order_id=(select order_id from test_external_orders where n=12)),'future operational binding preserves canonical rate and holds future purchase');
-- Paused or tracking-only current scope cannot be newly configured/paid.
update public.products set tracking_mode='tracking_only',tracking_only_funnel_id='ac570000-0000-4000-8000-000000000002',tracking_only_destination_url_snapshot='https://marathon.example.invalid',tracking_only_approved_by='ac570000-0000-4000-8000-000000000011',tracking_only_approved_at=now() where id='ac570000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.reject('select public.configure_admin_external_commission_terms(current_setting(''qa.terms.input'')::jsonb||jsonb_build_object(''request_id'',gen_random_uuid(),''expected_version'',2))','tracking-only product cannot get commercial terms');
reset role;
select pg_temp.make_order(13);select public.process_external_commissions();
select pg_temp.check_true((select blocker='commercial_scope_ineligible' and commission_minor=0 from public.external_commission_awards where order_id=(select order_id from test_external_orders where n=13)),'current tracking-only mode blocks earnings');
update public.funnels set is_default=true where id='ac570000-0000-4000-8000-000000000002';
insert into public.affiliate_links(id,affiliate_id,product_id,funnel_id,name,public_code,tracking_url,status,is_main,commercial_eligible) values('ac570000-0000-4000-8000-000000000084','ac570000-0000-4000-8000-000000000003','ac570000-0000-4000-8000-000000000001','ac570000-0000-4000-8000-000000000002','Demo main','demo_fixture_link','https://tracking.example.invalid/r/external-fixture/demo_fixture_link','paused',true,false);
insert into public.clicks(id,public_click_id,affiliate_link_id,affiliate_id,product_id,funnel_id,destination_url_snapshot,commercial_eligible) values('ac570000-0000-4000-8000-000000000085','demo_fixture_click_123456','ac570000-0000-4000-8000-000000000084','ac570000-0000-4000-8000-000000000003','ac570000-0000-4000-8000-000000000001','ac570000-0000-4000-8000-000000000002','https://marathon.example.invalid',false);
insert into public.acquisitions(id,product_id,affiliate_id,click_record_id,funnel_id,attribution_method,commercial_eligible) values('ac570000-0000-4000-8000-000000000086','ac570000-0000-4000-8000-000000000001','ac570000-0000-4000-8000-000000000003','ac570000-0000-4000-8000-000000000085','ac570000-0000-4000-8000-000000000002','deterministic_web',false);
select set_config('qa.demo.receipt',(select jsonb_set(core,'{input}',(core->'input')||jsonb_build_object('event_id',gen_random_uuid(),'order_id','ac570000-0000-4000-8000-000000000087','payment_intent_id','pi_demohistory','checkout_session_id','cs_test_demohistory','click_id','demo_fixture_click_123456','attribution',jsonb_build_object('kmaClick','demo_fixture_click_123456','status','unverified')))::text from test_external_orders where n=13),true);
select public.ingest_external_commerce(current_setting('qa.demo.receipt')::jsonb);
select public.record_external_commission_basis(jsonb_build_object('external_order_id','ac570000-0000-4000-8000-000000000087','stripe_account_id','acct_fixture','livemode',false,'eligible_basis_minor',8000,'total_minor',10000,'currency','USD','basis_policy','post_discount_excluding_tax_shipping','verified_at',clock_timestamp()));
update public.products set tracking_mode='commercial',tracking_only_funnel_id=null,tracking_only_destination_url_snapshot=null,tracking_only_approved_by=null,tracking_only_approved_at=null where id='ac570000-0000-4000-8000-000000000001';
select public.process_external_commissions();
select pg_temp.check_true((select w.commission_minor=0 and w.blocker='commercial_scope_ineligible' from public.external_commission_awards w join public.external_commerce_orders o on o.id=w.order_id where o.external_order_id='ac570000-0000-4000-8000-000000000087'),'immutable demo acquisition stays ineligible after product becomes commercial');
select pg_temp.check_true((select count(*)=0 from public.transactions) and (select count(*)=0 from public.commission_entries) and (select count(*)=0 from public.payouts),'external commission never forges legacy conversion or ledger');
select pg_temp.check_true(not has_function_privilege('authenticated','public.finish_creator_transfer_job(jsonb)','EXECUTE') and not has_function_privilege('anon','public.creator_connect_context(text,boolean)','EXECUTE'),'service settlement APIs and creator context protected');
select pg_temp.reject('delete from public.external_commission_ledger','financial ledger append only');
select pg_temp.reject('update public.external_settlement_items set amount_minor=1','reviewed line items immutable');
rollback;
